+                <InputSelect @bind-Value="model.InsuranceProvider" class="form-control">
+                    <option value="">-- Select --</option>
+                    <option value="Aetna">Aetna</option>
+                    <option value="BlueCross">BlueCross</option>
+                    <option value="Cigna">Cigna</option>
+                    <option value="UnitedHealth">UnitedHealth</option>
+                    <option value="None">None</option>
+                </InputSelect>
+                <ValidationMessage For="() => model.InsuranceProvider" />
+            </label>
+        </div>
+    </fieldset>
+
+    @if (!showStep2)
+    {
+        <button type="button" class="btn btn-primary" @onclick="CheckAvailability"
+                disabled="@isChecking">
+            @(isChecking ? "Checking..." : "Check Availability")
+        </button>
+    }
+
+    @if (showStep2)
+    {
+        <fieldset>
+            <legend>Appointment Details</legend>
+
+            <div class="mb-3">
+                <label class="form-label">
+                    Preferred Doctor
+                    <InputSelect @bind-Value="model.Doctor" class="form-control">
+                        <option value="">-- Select --</option>
+                        @foreach (var doc in doctors)
+                        {
+                            <option value="@doc.Name">@doc.Name</option>
+                        }
+                    </InputSelect>
+                    <ValidationMessage For="() => model.Doctor" />
+                </label>
+            </div>
+
+            <div class="mb-3">
+                <label class="form-label">
+                    Appointment Date
+                    <InputDate @bind-Value="model.AppointmentDate" class="form-control" />
+                    <ValidationMessage For="() => model.AppointmentDate" />
+                </label>
+            </div>
+
+            <div class="mb-3">
+                <label class="form-label">
+                    Time Slot
+                    <InputSelect @bind-Value="model.TimeSlot" class="form-control"
+                                 disabled="@(availableSlots.Count == 0)">
+                        <option value="">-- Select --</option>
+                        @foreach (var slot in availableSlots)
+                        {
+                            <option value="@slot">@slot</option>
+                        }
+                    </InputSelect>
+                    <ValidationMessage For="() => model.TimeSlot" />
+                </label>
+            </div>
+
+            @if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
+            {
+                <button type="button" class="btn btn-outline-secondary btn-sm mb-3"
+                        @onclick="LoadTimeSlots">
+                    Refresh Available Slots
+                </button>
+            }
+
+            <div class="mb-3">
+                <label class="form-label">
+                    Reason for Visit
+                    <InputTextArea @bind-Value="model.Reason" class="form-control" rows="3" />
+                    <ValidationMessage For="() => model.Reason" />
+                </label>
+                @if (!string.IsNullOrEmpty(model.Reason))
+                {
+                    <small>@model.Reason.Length / 500 characters</small>
+                }
+            </div>
+        </fieldset>
+
+        <button type="submit" class="btn btn-success" disabled="@isSubmitting">
+            @(isSubmitting ? "Booking..." : "Book Appointment")
+        </button>
+    }
+</EditForm>
+
+@if (isBooked)
+{
+    <div class="alert alert-success mt-3">
+        Appointment booked successfully for <strong>@model.Name</strong>
+        with <strong>@model.Doctor</strong> on @model.AppointmentDate?.ToString("MMM dd, yyyy")
+        at @model.TimeSlot.
+    </div>
+}
+
+@code {
+    private AppointmentModel model = new();
+    private EditContext? editContext;
+    private CustomValidator? customValidator;
+
+    private List<DoctorInfo> doctors = [];
+    private List<string> availableSlots = [];
+    private bool showStep2;
+    private bool isChecking;
+    private bool isSubmitting;
+    private bool isBooked;
+
+    // Fields that belong to step 1 for partial validation
+    private static readonly string[] Step1Fields =
+        [nameof(AppointmentModel.Name), nameof(AppointmentModel.Email),
+         nameof(AppointmentModel.Phone), nameof(AppointmentModel.InsuranceProvider)];
+
+    protected override async Task OnInitializedAsync()
+    {
+        editContext = new EditContext(model);
+        doctors = await AppointmentService.GetDoctorsAsync();
+    }
+
+    private async Task CheckAvailability()
+    {
+        isChecking = true;
+        customValidator?.ClearErrors();
+
+        // Validate only step 1 fields via DataAnnotations
+        var step1Valid = ValidateStep1();
+        if (!step1Valid)
+        {
+            isChecking = false;
+            return;
+        }
+
+        // Server-side validation needs a doctor, but at this stage we just check patient fields.
+        // We advance to step 2 so the user can pick a doctor and slot.
+        showStep2 = true;
+
+        // Pre-load time slots for tomorrow as default
+        if (model.AppointmentDate is null)
+        {
+            model.AppointmentDate = DateOnly.FromDateTime(DateTime.Today.AddDays(1));
+        }
+
+        if (doctors.Count > 0 && string.IsNullOrEmpty(model.Doctor))
+        {
+            model.Doctor = doctors[0].Name;
+        }
+
+        await LoadTimeSlots();
+        isChecking = false;
+    }
+
+    private bool ValidateStep1()
+    {
+        // Trigger validation and check only step 1 fields
+        editContext!.Validate();
+        foreach (var field in Step1Fields)
+        {
+            var fi = editContext.Field(field);
+            if (editContext.GetValidationMessages(fi).Any())
+            {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private async Task LoadTimeSlots()
+    {
+        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
+        {
+            availableSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
+                model.Doctor, model.AppointmentDate.Value);
+            // Clear selection if previously selected slot is no longer available
+            if (!string.IsNullOrEmpty(model.TimeSlot) && !availableSlots.Contains(model.TimeSlot))
+            {
+                model.TimeSlot = null;
+            }
+        }
+    }
+
+    private async Task HandleSubmit()
+    {
+        isSubmitting = true;
+        isBooked = false;
+        customValidator?.ClearErrors();
+
+        var errors = await AppointmentService.ValidatePatientAsync(
+            model.Email!, model.InsuranceProvider!, model.Doctor!, model.TimeSlot!);
+
+        if (errors.Count > 0)
+        {
+            customValidator!.DisplayErrors(errors);
+            isSubmitting = false;
+            return;
+        }
+
+        // Simulate booking
+        await Task.Delay(500);
+        isBooked = true;
+        isSubmitting = false;
+    }
+}
+

